71	export function buildGraph(args) {
72	  const g = new Graph();
73	  g.addWeightedEdge(args.a, args.b, 1);
74	  g.addWeightedEdge(args.b, args.c, 2);
75	  g.addWeightedEdge(args.c, args.d, 3);
76	  g.addWeightedEdge(args.d, args.e, 4);
77	  g.addWeightedEdge(args.a, args.e, 5);
78	  return g;
79	}

1	// Minimum spanning tree/forest using stable Kruskal's algorithm.
2	// Node labels are BigInt; edge weights are Number. No external modules.
3	
4	export function minimumSpanningTree(graph) {
5	  const parent = new Map();
6	  const size = new Map();
7	
8	  for (const node of graph.nodes()) {
9	    parent.set(node, node);
10	    size.set(node, 1);
11	  }
12	
13	  function find(node) {
14	    let root = node;
15	    while (parent.get(root) !== root) {
16	      root = parent.get(root);
17	    }
18	    while (parent.get(node) !== node) {
19	      const next = parent.get(node);
20	      parent.set(node, root);
21	      node = next;
22	    }
23	    return root;
24	  }
25	
26	  function union(u, v) {
27	    let rootU = find(u);
28	    let rootV = find(v);
29	    if (rootU === rootV) return false;
30	
31	    if (size.get(rootU) < size.get(rootV)) {
32	      [rootU, rootV] = [rootV, rootU];
33	    }
34	    parent.set(rootV, rootU);
35	    size.set(rootU, size.get(rootU) + size.get(rootV));
36	    return true;
37	  }
38	
39	  const sortedEdges = graph.edgeList()
40	    .map((edge, index) => ({ edge, index }))
41	    .sort((a, b) => {
42	      const weightDiff = a.edge.weight - b.edge.weight;
43	      return weightDiff !== 0 ? weightDiff : a.index - b.index;
44	    });
45	
46	  const edges = [];
47	  const members = new Map();
48	
49	  function addMembership(u, v) {
50	    if (!members.has(u)) members.set(u, new Set());
51	    members.get(u).add(v);
52	  }
53	
54	  for (const { edge } of sortedEdges) {
55	    // NetworkX Kruskal ignores self-loops when constructing the MST.
56	    if (edge.u === edge.v) continue;
57	    if (union(edge.u, edge.v)) {
58	      edges.push({ u: edge.u, v: edge.v, weight: edge.weight });
59	      addMembership(edge.u, edge.v);
60	      addMembership(edge.v, edge.u);
61	    }
62	  }
63	
64	  return {
65	    edges,
66	    edgeCount: edges.length,
67	    hasEdge(u, v) {
68	      const neighbors = members.get(u);
69	      return neighbors !== undefined && neighbors.has(v);
70	    },
71	  };
72	}

1	// Dijkstra shortest path matching NetworkX semantics.
2	// Node labels are BigInt; weights/distances are Number.
3	// Strict-less relaxation only; equal-distance ties are broken by a
4	// discovery counter so the first-discovered shortest path wins.
5	
6	class MinHeap {
7	  constructor() {
8	    this.items = []; // entries: {dist, count, node}
9	  }
10	
11	  less(a, b) {
12	    if (a.dist !== b.dist) return a.dist < b.dist;
13	    return a.count < b.count;
14	  }
15	
16	  push(entry) {
17	    const items = this.items;
18	    items.push(entry);
19	    let i = items.length - 1;
20	    while (i > 0) {
21	      const parent = (i - 1) >> 1;
22	      if (this.less(items[i], items[parent])) {
23	        [items[i], items[parent]] = [items[parent], items[i]];
24	        i = parent;
25	      } else {
26	        break;
27	      }
28	    }
29	  }
30	
31	  pop() {
32	    const items = this.items;
33	    const top = items[0];
34	    const last = items.pop();
35	    if (items.length > 0) {
36	      items[0] = last;
37	      let i = 0;
38	      const n = items.length;
39	      for (;;) {
40	        const left = 2 * i + 1;
41	        const right = left + 1;
42	        let smallest = i;
43	        if (left < n && this.less(items[left], items[smallest])) smallest = left;
44	        if (right < n && this.less(items[right], items[smallest])) smallest = right;
45	        if (smallest === i) break;
46	        [items[i], items[smallest]] = [items[smallest], items[i]];
47	        i = smallest;
48	      }
49	    }
50	    return top;
51	  }
52	
53	  get size() {
54	    return this.items.length;
55	  }
56	}
