58	export function dijkstraPath(graph, source, target) {
59	  if (source === target) {
60	    return { length: 0, path: [source], zeroInteger: true };
61	  }
62	
63	  const dist = new Map(); // settled node -> final distance
64	  const seen = new Map(); // discovered node -> best known distance
65	  const pred = new Map(); // node -> predecessor on shortest path
66	  const heap = new MinHeap();
67	  let count = 0;
68	
69	  seen.set(source, 0);
70	  heap.push({ dist: 0, count: count++, node: source });
71	
72	  while (heap.size > 0) {
73	    const { dist: d, node: u } = heap.pop();
74	    if (dist.has(u)) continue;
75	    dist.set(u, d);
76	    if (u === target) break;
77	
78	    for (const v of graph.neighbors(u)) {
79	      const w = graph.getWeight(u, v);
80	      const vuDist = d + w;
81	      if (dist.has(v)) {
82	        if (vuDist < dist.get(v)) {
83	          throw new Error('Dijkstra: negative weights are not supported');
84	        }
85	      } else if (!seen.has(v) || vuDist < seen.get(v)) {
86	        seen.set(v, vuDist);
87	        pred.set(v, u);
88	        heap.push({ dist: vuDist, count: count++, node: v });
89	      }
90	    }
91	  }
92	
93	  if (!dist.has(target)) {
94	    throw new Error(`No path between ${String(source)} and ${String(target)}`);
95	  }
96	
97	  const path = [target];
98	  while (path[path.length - 1] !== source) {
99	    path.push(pred.get(path[path.length - 1]));
100	  }
101	  path.reverse();
102	
103	  return { length: dist.get(target), path, zeroInteger: false };
104	}

1	// Traversal algorithms: networkx-compatible bfs_edges / dfs_edges.
2	// Pure JavaScript, ESM, no external modules. Node labels are BigInt.
3	
4	// networkx bfs_edges: breadth-first over neighbors in adjacency insertion
5	// order, marking nodes as visited at enqueue time.
6	export function bfsEdges(graph, source) {
7	  const edges = [];
8	  const visited = new Set([source]);
9	  const queue = [source];
10	  let head = 0;
11	  while (head < queue.length) {
12	    const u = queue[head++];
13	    for (const v of graph.neighbors(u)) {
14	      if (!visited.has(v)) {
15	        visited.add(v);
16	        queue.push(v);
17	        edges.push([u, v]);
18	      }
19	    }
20	  }
21	  return edges;
22	}
23	
24	// networkx dfs_edges: iterative stack of resumable neighbor iterators.
25	// Each stack entry is [parent, iterator]; children are explored depth-first
26	// in adjacency insertion order (no reversal of neighbors).
27	export function dfsEdges(graph, source) {
28	  const edges = [];
29	  const visited = new Set([source]);
30	  const stack = [[source, graph.neighbors(source)[Symbol.iterator]()]];
31	  while (stack.length > 0) {
32	    const top = stack[stack.length - 1];
33	    const parent = top[0];
34	    const step = top[1].next();
35	    if (step.done) {
36	      stack.pop();
37	      continue;
38	    }
39	    const child = step.value;
40	    if (!visited.has(child)) {
41	      visited.add(child);
42	      edges.push([parent, child]);
43	      stack.push([child, graph.neighbors(child)[Symbol.iterator]()]);
44	    }
45	  }
46	  return edges;
47	}

1	// Node connectivity for the constrained quotient-of-cycle graph.
2	// Contract:
3	//   - disconnected graph -> 0
4	//   - connected graph -> minimum NetworkX degree (self-loop contributes 2)
5	//   - a single node returns its own degree (self-loop => 2)
6	
7	export function nodeConnectivity(graph) {
8	  const nodes = [...graph.nodes()];
9	  const n = nodes.length;
10	  if (n === 0) return 0;
11	  if (n === 1) return graph.degree(nodes[0]);
12	
13	  // Connectivity check: BFS from the first node using adjacency iterators.
14	  const visited = new Set([nodes[0]]);
15	  const queue = [nodes[0]];
16	  for (let head = 0; head < queue.length; head++) {
17	    for (const neighbor of graph.neighbors(queue[head])) {
18	      if (!visited.has(neighbor)) {
19	        visited.add(neighbor);
20	        queue.push(neighbor);
21	      }
22	    }
23	  }
24	  if (visited.size < n) return 0;
25	
26	  // Connected: node connectivity equals the minimum degree.
27	  // graph.degree already counts a self-loop twice, matching NetworkX.
28	  let minDegree = Infinity;
29	  for (const node of nodes) {
30	    const d = graph.degree(node);
31	    if (d < minDegree) minDegree = d;
32	  }
33	  return minDegree;
34	}

