import { parseCli } from './lib/cli.mjs';
import { buildGraph } from './lib/graph.mjs';
import { minimumSpanningTree } from './lib/algorithms/mst.mjs';
import { dijkstraPath } from './lib/algorithms/dijkstra.mjs';
import { bfsEdges, dfsEdges } from './lib/algorithms/traversal.mjs';
import { nodeConnectivity } from './lib/algorithms/connectivity.mjs';
import {
  formatBool,
  formatFloat,
  formatPathLength,
  formatNodeList,
  formatEdgeList,
} from './lib/pyformat.mjs';

const prog = (process.argv[1] || 'test10.mjs').split(/[\\/]/).pop();
const parsed = parseCli(process.argv.slice(2), prog);

if (parsed.kind === 'help') {
  process.stdout.write(parsed.text);
  process.exit(0);
}
if (parsed.kind === 'error') {
  process.stderr.write(parsed.text);
  process.exit(2);
}

const args = parsed.args;
const graph = buildGraph(args);
const mst = minimumSpanningTree(graph);
const shortest = dijkstraPath(graph, args.a, args.e);

const lines = [
  String(graph.numberOfEdges()),
  formatFloat(graph.getWeight(args.a, args.b)),
  String(mst.edgeCount),
  formatBool(mst.hasEdge(args.a, args.b)),
  formatPathLength(shortest),
  formatNodeList(shortest.path),
  formatEdgeList(bfsEdges(graph, args.a)),
  formatEdgeList(dfsEdges(graph, args.a)),
  String(nodeConnectivity(graph)),
];

process.stdout.write(lines.join('\n') + '\n');
